import{_ as a,o,c as n,ai as t}from"./chunks/framework.C0JxkKN5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"HelpCenter/Account&Settings.md","filePath":"HelpCenter/Account&Settings.md"}'),r={name:"HelpCenter/Account&Settings.md"};function i(s,e,c,p,d,l){return o(),n("div",null,[...e[0]||(e[0]=[t('<h3 id="_1-sign-up-log-in-terndrop-account" tabindex="-1">1. Sign up/log in TernDrop account <a class="header-anchor" href="#_1-sign-up-log-in-terndrop-account" aria-label="Permalink to “1. Sign up/log in TernDrop account”">​</a></h3><p>Click the “Register” button on the TernDrop main page.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773387902488-3263a077-45ca-4530-a96f-095e79638288.png" alt="1773387902488 3263a077 45ca 4530 a96f 095e79638288"></p><p>Proceed to the registration page and fill in your usename, email address,full name, and password. After all the blanks are filled in, click the “Register Now” button to complete the registration process.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773388021113-ad92e609-b63b-4f09-9e0e-07bf91be52b3.png" alt="1773388021113 ad92e609 b63b 4f09 9e0e 07bf91be52b3"></p><p>If you have any questions about the registration or logging in, please contact us through the online customer service or support email.</p><p>Customer Service Email : <a href="mailto:support@terndrop.com" target="_blank" rel="noreferrer">support@terndrop.com</a></p><h3 id="_2-change-reset-terndrop-account-password" tabindex="-1">2. Change &amp; reset TernDrop account password <a class="header-anchor" href="#_2-change-reset-terndrop-account-password" aria-label="Permalink to “2. Change &amp; reset TernDrop account password”">​</a></h3><p>Your registered email can not be changed once it is registered.</p><p>If you want to recover your password, click &quot;Forgot&quot;on the reset password page. Just enter your email address and you will receive the verification code, then fill in new password and confirm new password.Click &quot;confirm&quot;to reset your password.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773388527916-98eb8f77-d813-4ce6-85b6-86dc59b44384.png" alt="1773388527916 98eb8f77 d813 4ce6 85b6 86dc59b44384"></p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773388596366-ef071dd3-d57b-487e-a7e9-cc93f043084b.png" alt="1773388596366 ef071dd3 d57b 487e a7e9 cc93f043084b"></p><p>If you want to reset your password, you can login your terndrop account enter Membership Center &amp; Change Password, you will be able toreset password in this page.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773388972967-c6a927ea-556f-48ae-bb5d-798fcbd0691c.png" alt="1773388972967 c6a927ea 556f 48ae bb5d 798fcbd0691c"></p><h3 id="_3-shipping-address-filling" tabindex="-1">3. <strong>Shipping address filling</strong> <a class="header-anchor" href="#_3-shipping-address-filling" aria-label="Permalink to “3. Shipping address filling”">​</a></h3><p>You can log in terndrop account and click the right top part in your account name, enter Membership Center &amp; Shipping Address. Then follow the prompts to fill in information including receipient, contact phone number, postal code, and detailed delivery address.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773400820373-da3b7e93-0a59-4682-a237-59e6de977dcd.png" alt="1773400820373 da3b7e93 0a59 4682 a237 59e6de977dcd"></p><h3 id="_4-terndrop-account-profile-information" tabindex="-1">4. TernDrop account profile information <a class="header-anchor" href="#_4-terndrop-account-profile-information" aria-label="Permalink to “4. TernDrop account profile information”">​</a></h3><p>You can log in terndrop account and click the right top part in your account name, you will be able to see the profile page, you can edit your company name, address, and contact informatio. After you complete the editing, click save button to complete the process.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773400500251-f1ec18c8-5811-4009-9c0a-1a38e735e1d5.png" alt="1773400500251 f1ec18c8 5811 4009 9c0a 1a38e735e1d5"></p>',20)])])}const h=a(r,[["render",i]]);export{u as __pageData,h as default};
